  // Monitor iframe for successful E-REDES login
  monitorIframeLogin(iframe, resolve, reject, overlay) {
    const checkInterval = setInterval(() => {
      try {
        // Try to detect successful login by URL change or page content
        const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
        const currentUrl = iframe.contentWindow.location.href;

        // Check if redirected to dashboard or success page
        if (currentUrl.includes('/dashboard') ||
            currentUrl.includes('/home') ||
            currentUrl.includes('/area-cliente') ||
            currentUrl.includes('/consumos') ||
            currentUrl.includes('/faturas') ||
            iframeDoc.querySelector('[data-test="dashboard"]') ||
            iframeDoc.querySelector('.dashboard-content')) {

          clearInterval(checkInterval);
          this.extractAuthDataFromIframe(iframe)
            .then(authData => {
              document.body.removeChild(overlay);
              resolve(authData);
            })
            .catch(error => {
              clearInterval(checkInterval);
              document.body.removeChild(overlay);
              reject(error);
            });
        }

        // Check for login errors
        const errorElements = iframeDoc.querySelectorAll('.error, .alert-danger, [class*="error"], [class*="invalid"]');
        if (errorElements.length > 0) {
          const errorText = Array.from(errorElements)
            .map(el => el.textContent.trim())
            .filter(text => text.length > 0)
            .join('; ');

          if (errorText) {
            console.warn('E-REDES login error detected:', errorText);
          }
        }

      } catch (error) {
        // Cross-origin restrictions - this is expected
        // We'll continue monitoring and use other detection methods
      }
    }, 1000);

    // Also listen for postMessage from iframe (if E-REDES implements it)
    const messageHandler = (event) => {
      if (event.origin === 'https://balcaodigital.e-redes.pt' ||
          event.origin === this.proxyUrl) {
        if (event.data.type === 'EREDES_LOGIN_SUCCESS') {
          clearInterval(checkInterval);
          window.removeEventListener('message', messageHandler);

          const authData = {
            success: true,
            token: event.data.token,
            cookies: event.data.cookies,
            user: event.data.user
          };

          this.storeAuthData(authData);
          document.body.removeChild(overlay);
          resolve(authData);
        } else if (event.data.type === 'EREDES_LOGIN_ERROR') {
          clearInterval(checkInterval);
          window.removeEventListener('message', messageHandler);
          document.body.removeChild(overlay);
          reject(new Error(event.data.message || 'Login failed'));
        }
      }
    };

    window.addEventListener('message', messageHandler);

    // Cleanup on overlay removal
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'childList') {
          if (!document.body.contains(overlay)) {
            clearInterval(checkInterval);
            window.removeEventListener('message', messageHandler);
            observer.disconnect();
          }
        }
      });
    });
    observer.observe(document.body, { childList: true });
  }

